import sys
from collections import deque

def solve():
    input = sys.stdin.read
    data = input().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    K = int(data[2])

    # Matriz para marcar células vigiadas: linhas 1..M, colunas 1..N
    # Usaremos 1-indexado
    blocked = [[False] * (N + 1) for _ in range(M + 1)]

    idx = 3
    for _ in range(K):
        c = int(data[idx])
        r = int(data[idx+1])
        d = data[idx+2]
        idx += 3

        if d == 'N':
            for row in range(1, r + 1):
                blocked[row][c] = True
        elif d == 'S':
            for row in range(r, M + 1):
                blocked[row][c] = True
        elif d == 'L':
            for col in range(c, N + 1):
                blocked[r][col] = True
        elif d == 'O':
            for col in range(1, c + 1):
                blocked[r][col] = True

    # Verifica se a entrada ou a saída estão bloqueadas
    if blocked[1][1] or blocked[M][N]:
        print('N')
        return

    # BFS para verificar caminho de (1, 1) até (M, N)
    queue = deque([(1, 1)])
    visited = [[False] * (N + 1) for _ in range(M + 1)]
    visited[1][1] = True

    dr = [-1, 1, 0, 0]
    dc = [0, 0, -1, 1]

    possible = False
    while queue:
        r, c = queue.popleft()
        if r == M and c == N:
            possible = True
            break

        for i in range(4):
            nr = r + dr[i]
            nc = c + dc[i]
            if 1 <= nr <= M and 1 <= nc <= N:
                if not visited[nr][nc] and not blocked[nr][nc]:
                    visited[nr][nc] = True
                    queue.append((nr, nc))

    if possible:
        print('S')
    else:
        print('N')

if __name__ == '__main__':
    solve()
